from itertools import starmap, zip_longest


def apply_pairs(pairs, fn):
    return list(starmap(fn, pairs))


def parallel_max(lists):
    return [max(values) for values in zip_longest(*lists, fillvalue=float('-inf'))]


def interleave_longest(a, b):
    sentinel = object()
    result = []
    for x, y in zip_longest(a, b, fillvalue=sentinel):
        if x is not sentinel:
            result.append(x)
        if y is not sentinel:
            result.append(y)
    return result
